struct Cell { int row, column; };

string reconstructPath(Cell startCell, Cell targetCell,
                       const vector<vector<Cell>>& predecessor,
                       const vector<vector<char>>& moveUsed) {
    string reversedPath;
    Cell currentCell = targetCell;
    while (!(currentCell.row == startCell.row && currentCell.column == startCell.column)) {
        reversedPath.push_back(moveUsed[currentCell.row][currentCell.column]);
        currentCell = predecessor[currentCell.row][currentCell.column];
    }
    reverse(reversedPath.begin(), reversedPath.end());
    return reversedPath;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int rowCount, columnCount;
    cin >> rowCount >> columnCount;
    vector<string> grid(rowCount);
    for (string& row : grid) cin >> row;

    Cell startCell{-1, -1}, targetCell{-1, -1};
    for (int row = 0; row < rowCount; ++row) {
        for (int column = 0; column < columnCount; ++column) {
            if (grid[row][column] == 'A') startCell = {row, column};
            if (grid[row][column] == 'B') targetCell = {row, column};
        }
    }

    vector<vector<int>> distance(rowCount, vector<int>(columnCount, -1));
    vector<vector<Cell>> predecessor(rowCount, vector<Cell>(columnCount, {-1, -1}));
    vector<vector<char>> moveUsed(rowCount, vector<char>(columnCount, 0));
    const int rowDelta[4] = {-1, 1, 0, 0};
    const int columnDelta[4] = {0, 0, -1, 1};
    const char moveName[4] = {'U', 'D', 'L', 'R'};
    queue<Cell> pendingCells;
    distance[startCell.row][startCell.column] = 0;
    pendingCells.push(startCell);

    while (!pendingCells.empty()) {
        Cell currentCell = pendingCells.front();
        pendingCells.pop();
        for (int direction = 0; direction < 4; ++direction) {
            int nextRow = currentCell.row + rowDelta[direction];
            int nextColumn = currentCell.column + columnDelta[direction];
            bool insideGrid = 0 <= nextRow && nextRow < rowCount && 0 <= nextColumn && nextColumn < columnCount;
            if (!insideGrid || grid[nextRow][nextColumn] == '#' || distance[nextRow][nextColumn] != -1) continue;
            distance[nextRow][nextColumn] = distance[currentCell.row][currentCell.column] + 1;
            predecessor[nextRow][nextColumn] = currentCell;
            moveUsed[nextRow][nextColumn] = moveName[direction];
            pendingCells.push({nextRow, nextColumn});
        }
    }

    if (distance[targetCell.row][targetCell.column] == -1) { cout << "IMPOSSIBLE\n"; return 0; }
    string path = reconstructPath(startCell, targetCell, predecessor, moveUsed);
    cout << "YES\n" << path.size() << "\n" << path << "\n";
}
